## Zig 0.16 mag – HTTP & párhuzamosság

A Zig oldal a `std.Io.Threaded` architektúrára épül, amit a `quantum-encoding/zig-http-concurrent` könyvtár is alkalmaz . Minden worker szál saját `HttpClient` példányt kap — így nulla a versenyhelyzet, valódi párhuzamosság érhető el.

```zig
// src/http_client.zig — Zig 0.16.0
const std = @import("std");
const http = std.http;

pub const HttpClient = struct {
    allocator: std.mem.Allocator,
    io_threaded: *std.Io.Threaded,
    client: http.Client,

    pub fn init(allocator: std.mem.Allocator) !HttpClient {
        const io_threaded = try allocator.create(std.Io.Threaded);
        io_threaded.* = std.Io.Threaded.init(allocator, .{});
        const io_handle = io_threaded.io();
        return .{
            .allocator = allocator,
            .io_threaded = io_threaded,
            .client = http.Client{
                .allocator = allocator,
                .io = io_handle,
            },
        };
    }

    pub fn deinit(self: *HttpClient) void {
        self.client.deinit();
        self.io_threaded.deinit();
        self.allocator.destroy(self.io_threaded);
    }

    pub fn get(self: *HttpClient, url: []const u8, headers: []const http.Header) !Response {
        // ... implementáció
    }

    pub fn post(self: *HttpClient, url: []const u8, body: []const u8, headers: []const http.Header) !Response {
        // ... implementáció
    }
};
```

```zig
// src/parallel.zig — párhuzamos worker pool
const std = @import("std");
const HttpClient = @import("http_client.zig").HttpClient;

pub const TaskResult = struct {
    id: u32,
    payload: []const u8,
    status: u16,
    allocator: std.mem.Allocator,
};

pub const Worker = struct {
    allocator: std.mem.Allocator,
    tasks: []const Task,
    results: *std.ArrayList(TaskResult),
    mutex: *std.Thread.Mutex,

    pub fn run(self: @This()) void {
        var client = HttpClient.init(self.allocator) catch unreachable;
        defer client.deinit();

        for (self.tasks) |task| {
            const resp = client.post(task.url, task.body, task.headers) catch continue;
            defer resp.deinit();

            self.mutex.lock();
            defer self.mutex.unlock();
            self.results.append(.{
                .id = task.id,
                .payload = resp.body,
                .status = resp.status,
                .allocator = self.allocator,
            }) catch {};
        }
    }
};
```

## API integrációk Zigben

### Exa Websets (Akadémiai keresés)

Az Exa API (a paste.txt-ben `szarrago` névvel dokumentálva) `` base URL-en érhető el, aszinkron webset-alapú kereséssel.[1]

```zig
// src/apis/exa.zig
pub fn createWebset(client: *HttpClient, api_key: []const u8, query: []const u8, count: u32) ![]u8 {
    const body = try std.fmt.allocPrint(client.allocator,
        \\{{"search":{{"query":"{s}","count":{d}}}}}
    , .{ query, count });
    defer client.allocator.free(body);

    const headers = &[_]http.Header{
        .{ .name = "x-api-key", .value = api_key },
        .{ .name = "content-type", .value = "application/json" },
        .{ .name = "accept", .value = "application/json" },
    };
    const resp = try client.post("", body, headers);
    defer resp.deinit();
    return client.allocator.dupe(u8, resp.body);
}

pub fn waitUntilIdle(client: *HttpClient, api_key: []const u8, webset_id: []const u8) ![]u8 {
    const url = try std.fmt.allocPrint(client.allocator,
        "", .{webset_id});
    defer client.allocator.free(url);
    const headers = &[_]http.Header{
        .{ .name = "x-api-key", .value = api_key },
    };
    // polling loop 5s intervallumonként
    while (true) {
        const resp = try client.get(url, headers);
        // JSON parse: ha status == "idle" → return
        if (std.mem.indexOf(u8, resp.body, "\"idle\"") != null) {
            return client.allocator.dupe(u8, resp.body);
        }
        std.time.sleep(5 * std.time.ns_per_s);
        resp.deinit();
    }
}
```

