```v
// v/orchestrator.v — párhuzamos pipeline
module orchestrator

import zig_ffi
import json
import sync
import os

pub struct PipelineConfig {
pub:
    exa_api_key     string
    gcp_token       string
    gcp_project     string
    hf_token        string
    github_token    string
    x_bearer        string
    query           string
    vertex_model    string = 'gemini-1.5-pro'
}

pub struct PipelineResult {
pub mut:
    exa_webset_id   string
    github_repos    string
    x_tweets        string
    vertex_response string
    hf_response     string
}

pub fn run_parallel_pipeline(cfg PipelineConfig) PipelineResult {
    mut result := PipelineResult{}
    mut wg := sync.WaitGroup{}

    // 1. Exa Webset indítása
    wg.add(1)
    spawn fn  {
        defer wg.done()
        raw := zig_ffi.exa_create_webset(cfg.exa_api_key, cfg.query, 50)
        result.exa_webset_id = raw
    }()

    // 2. GitHub keresés
    wg.add(1)
    spawn fn  {
        defer wg.done()
        result.github_repos = zig_ffi.github_search(cfg.github_token,
            '${cfg.query} language:zig language:v stars:>10')
    }()

    // 3. X (Twitter) keresés
    wg.add(1)
    spawn fn  {
        defer wg.done()
        result.x_tweets = zig_ffi.x_search(cfg.x_bearer, cfg.query)
    }()

    // 4. Vertex AI generálás
    wg.add(1)
    spawn fn  {
        defer wg.done()
        payload := '{"query": "${cfg.query}", "task": "summarize and analyze academic relevance"}'
        result.vertex_response = zig_ffi.vertex_generate(
            cfg.gcp_token, cfg.gcp_project, cfg.vertex_model, payload)
    }()

    // 5. Hugging Face inference
    wg.add(1)
    spawn fn  {
        defer wg.done()
        hf_payload := '{"inputs": "${cfg.query}"}'
        result.hf_response = zig_ffi.hf_infer(cfg.hf_token,
            'sentence-transformers/all-MiniLM-L6-v2', hf_payload)
    }()

    wg.wait()
    return result
}
```

