// v/processors/brightdata.v
module brightdata

import net.http

pub struct BrightDataClient {
pub:
    api_key string
    zone    string = 'datacenter'
}

pub fn (c BrightDataClient) scrape_url(target_url string) string {
    proxy_url := ''
    mut req := http.Request{
        method: .get
        url:    target_url
    }
    // Proxy auth header
    import encoding.base64
    creds := base64.encode('brd-customer-XXXXX-zone-${c.zone}:${c.api_key}'.bytes())
    req.add_header(.proxy_authorization, 'Basic ${creds}')
    req.add_custom_header('x-brd-api-key', c.api_key) or {}
    resp := req.do() or { return '{"error": "${err}"}' }
    return resp.body
}

pub fn (c BrightDataClient) web_unlocker(target_url string) string {
    payload := '{"url": "${target_url}", "zone": "${c.zone}"}'
    mut req := http.Request{
        method: .post
        url:    ''
        data:   payload
    }
    req.add_header(.authorization, 'Bearer ${c.api_key}')
    req.add_header(.content_type, 'application/json')
    resp := req.do() or { return '' }
    return resp.body
}
